package com.javasmyths.mercenary;
import java.util.*;
public class RulesCheck {
 static void check(boolean v,String m){if(!v)throw new AssertionError(m);}
 public static void main(String[] args){int complete=0,dead=0,schools=0;for(int seed=0;seed<1000;seed++){Soldier s=new Soldier();s.randomState=seed;s.service=seed%2==0?"Army":"Marines";s.arm=s.service.equals("Army")?Rules.ARMS[seed%3]:"Marine Infantry";s.stats=new int[]{9,9,9,9,9,9};Rules.training(s);check(s.years==1,"Training consumes first year");check(s.skills.getOrDefault("Combat Rifleman",0)>=1,"Basic rifleman");int guard=0;while(!s.isFinished()&&guard++<600){switch(s.phase){case "ASSIGN":Rules.assignment(s,true,s.officer,true,true,"");break;case "SKILL":Rules.skillRoll(s,"MOS");Rules.advance(s);break;case "CHOICE":String choice=Rules.choices(s).get(0),generic=s.pending.remove(0);s.skills.merge(generic.equals("Gun Combat")?choice:generic+": "+choice,1,Integer::sum);if(s.pending.isEmpty())s.phase=s.next;break;case "CROSS":String cross=s.arm.equals("Support")?"Artillery":"Support";s.qualified.add(cross);String old=s.arm;s.arm=cross;Rules.skillRoll(s,"MOS");s.arm=old;Rules.advance(s);break;case "TERM":if(s.years>=16)Rules.muster(s);else{s.promoted=false;s.phase="ASSIGN";}break;case "BENEFITS":Rules.benefit(s,"Material",true);break;default:throw new AssertionError("Unexpected phase "+s.phase);}}
 check(guard<600,"Career stalled");check(s.pending.isEmpty()||s.phase.equals("DEAD"),"Unresolved choices");check(s.rank<=(s.officer?10:9),"Rank overflow");if(s.phase.equals("FINAL"))complete++;else dead++;schools+=s.schools.size();}
 Soldier s=new Soldier();s.arm="Commando";check(Rules.outcomes(s,0)[0]==3,"Commando training risk");s.arm="Marine Infantry";s.service="Marines";check(Rules.outcomes(s,4)[1]==5,"Marine raid medal target");check(Rules.general("Support",2).equals("Staff"),"Support assignment");s.skills.put("Zero-G Combat",1);s.pending.add("Gun Combat");check(Rules.choices(s).contains("Zero-G Weapons"),"Zero-G qualification");s.skills.clear();check(!Rules.choices(s).contains("Zero-G Weapons"),"Zero-G prerequisite");System.out.println("PASS: 1000 seeded careers; "+complete+" retired, "+dead+" casualties, "+schools+" special postings.");
 }
}
